**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("pomiary.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();

    double suma = 0;
    for (int i = 0; i < n; i++) suma += tab[i];
    double sr = suma / n;

    double minOdl = fabs(tab[0] - sr);
    int najblPos = 0;
    for (int i = 1; i < n; i++) {
        double odl = fabs(tab[i] - sr);
        if (odl < minOdl) {
            minOdl = odl;
            najblPos = i;
        }
    }

    cout << fixed << setprecision(2);
    cout << "a) Srednia: " << sr << endl;
    cout << "b) Najblizszy sredniej: " << tab[najblPos]
         << " (pozycja: " << najblPos + 1
         << ", odleglosc: " << minOdl << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Dwa przebiegi — pierwszy oblicza srednia, drugi szuka elementu minimalizujacego odleglosc od sredniej. Uzywamy fabs() bo pracujemy na double.

Weryfikacja:
- Suma: 15+42+8+37+25+50+12+33+28+20 = 270, srednia = 27.00
- Odleglosci: |15-27|=12, |42-27|=15, |8-27|=19, |37-27|=10, |25-27|=2, |50-27|=23, |12-27|=15, |33-27|=6, |28-27|=1, |20-27|=7
- Min odleglosc: 1 dla elementu 28 (pozycja 9).
